import{_ as r,a0 as l,w as u,s as x,ao as p,I as t,x as o,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Distrochooser 幫助 Linux 初學者選擇合適的 Linux 發行版 | LCTT x X-CMD","titleTemplate":false,"description":"Distrochooser 幫助 Linux 初學者選擇合適的 Linux 發行版 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Distrochooser 幫助 Linux 初學者選擇合適的 Linux 發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Distrochooser 幫助 Linux 初學者選擇合適的 Linux 發行版 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180802 Distrochooser Helps Linux Beginners To Choose A Suitable Linux Distribution","title":"Distrochooser 幫助 Linux 初學者選擇合適的 Linux 發行版","tag":"201809","desc":""},"relativePath":"201809/20180802 Distrochooser Helps Linux Beginners To Choose A Suitable Linux Distribution.md","filePath":"[post].md"}'),a={name:"201809/20180802 Distrochooser Helps Linux Beginners To Choose A Suitable Linux Distribution.md"};function d(L,i,h,m,g,D){const s=l("Link");return u(),x("div",null,[i[18]||(i[18]=p('<h1 id="distrochooser-幫助-linux-初學者選擇合適的-linux-發行版" tabindex="-1">Distrochooser 幫助 Linux 初學者選擇合適的 Linux 發行版 <a class="header-anchor" href="#distrochooser-幫助-linux-初學者選擇合適的-linux-發行版" aria-label="Permalink to “Distrochooser 幫助 Linux 初學者選擇合適的 Linux 發行版”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/distrochooser-logo-720x340.png" alt=""></p><p>你好 Linux 新手！今天，我為你們帶來了一個好消息！你也許想知道如何選擇合適的 Linux 發行版。當然，你可能已經諮詢過一些 Linux 專家來幫助你的需要選擇 Linux 發行版。你們中的一些人可能已經用 Google 搜索並瀏覽了各種資源、Linux 論壇、網站和Blog來尋找完美的發行版。好了，你不必再那樣做了。有了 <strong>Distrochooser</strong>，一個幫助你輕鬆找到 Linux 發行版的網站。</p><h3 id="distrochooser-如何幫助-linux-初學者選擇合適的-linux-發行版" tabindex="-1">Distrochooser 如何幫助 Linux 初學者選擇合適的 Linux 發行版？ <a class="header-anchor" href="#distrochooser-如何幫助-linux-初學者選擇合適的-linux-發行版" aria-label="Permalink to “Distrochooser 如何幫助 Linux 初學者選擇合適的 Linux 發行版？”">​</a></h3><p>Distrochooser 會根據你的答案向你詢問一系列問題並建議你嘗試不同的 Linux 發行版。激動嗎？太好了！讓我們繼續看看如何找到合適的 Linux 發行版。單擊以下鏈接開始。</p><p><img src="https://distrochooser.de/en" alt=""></p><p>你將被重定向到 Distrochooser 主頁，其中有一個小測試在等待你註冊。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/distrochooser-home-page.png" alt=""></p><p>你需要回答一系列問題（準確地説是 16 個問題）。問題同時有單選和多選。以下是完整的問題列表。</p><ol><li>軟件：使用情況</li><li>計算機知識</li><li>Linux 知識</li><li>安裝：預設</li><li>安裝：需要 Live 測試麼？</li><li>安裝：硬件支持</li><li>配置：幫助源</li><li>發行版：用户體驗概念</li><li>發行版：價格</li><li>發行版：範圍</li><li>發行版：意識形態</li><li>發行版：隱私</li><li>發行版：預設主題，圖標和壁紙</li><li>發行版：特色</li><li>軟件：管理</li><li>軟件：更新</li></ol><p>仔細閲讀問題並在相應問題下面選擇合適的答案。Distrochooser 提供了更多選擇來選擇接近完美的發行版。</p><ul><li>你總是可以跳過問題，</li><li>你可以隨時點擊“獲取結果”，</li><li>你可以任意順序回答，</li><li>你可以隨時刪除答案，</li><li>你可以在測試結束時對屬性進行加權，以強調對你來説重要的內容。</li></ul><p>選擇問題的答案後，單擊“Proceed”以轉到下一個問題。完成後，單擊“Get Result”按鈕。你也可以通過單擊答案下面的“Clear”按鈕隨時清除選擇。</p><h3 id="結果" tabindex="-1">結果？ <a class="header-anchor" href="#結果" aria-label="Permalink to “結果？”">​</a></h3><p>我以前不相信 Distrochooser 會找到我想要的東西。哦，我錯了！令我驚訝的是，它確實做得很好。結果對我來説幾乎是準確的。我期待 Arch Linux 在結果中，結果確實是在推薦第一位，接下來是其他 11 個建議，如 NixOS、Void Linux、Qubes OS、Scientific Linux、Devuan、Gentoo Linux、Bedrock Linux、Slackware、CentOS、Linux from scratch、Redhat Enterprise Linux。總共有 12 個推薦，每個結果都非常詳細，帶有發行版的描述和主頁。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/distrochooser-result.png" alt=""></p>',16)),t("p",null,[i[1]||(i[1]=o("我在 Reddit 上發佈了 Distrochooser 鏈接，80％ 的用户可以找到合適的 Linux 發行版。但是，我不會聲稱 Distrochooser 足以為每個人找到好結果。一些用户對調查結果感到失望，甚至結果與他們使用中或者想要使用的一點不接近。因此，我強烈建議你在嘗試任何 Linux 之前諮詢其他 Linux 專家、網站和論壇。你可以在",-1)),n(s,{href:"https://www.reddit.com/r/linux/comments/93p6az/distrochooser_helps_linux_beginners_to_choose_a/"},{default:e(()=>[...i[0]||(i[0]=[t("strong",null,"這裏",-1)])]),_:1}),i[2]||(i[2]=o("閲讀完整的 Reddit 討論。",-1))]),i[19]||(i[19]=t("p",null,"你在等什麼？進入 Distrochooser 網站併為你選擇合適的 Linux 發行版吧。",-1)),i[20]||(i[20]=t("p",null,"就是這些了。還有更多好東西。敬請期待！",-1)),i[21]||(i[21]=t("p",null,"乾杯!",-1)),i[22]||(i[22]=t("hr",null,null,-1)),t("p",null,[i[4]||(i[4]=o("via: ",-1)),n(s,{href:"https://www.ostechnix.com/distrochooser-helps-linux-beginners-to-choose-a-suitable-linux-distribution/"},{default:e(()=>[...i[3]||(i[3]=[o("https://www.ostechnix.com/distrochooser-helps-linux-beginners-to-choose-a-suitable-linux-distribution/",-1)])]),_:1})]),t("p",null,[i[9]||(i[9]=o("作者：",-1)),n(s,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...i[5]||(i[5]=[o("SK",-1)])]),_:1}),i[10]||(i[10]=o(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[6]||(i[6]=[o("lujun9972",-1)])]),_:1}),i[11]||(i[11]=o(" 譯者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:e(()=>[...i[7]||(i[7]=[o("geekpi",-1)])]),_:1}),i[12]||(i[12]=o(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:e(()=>[...i[8]||(i[8]=[o("wxy",-1)])]),_:1})]),t("p",null,[i[15]||(i[15]=o("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[13]||(i[13]=[o("LCTT",-1)])]),_:1}),i[16]||(i[16]=o(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:e(()=>[...i[14]||(i[14]=[o("Linux中國",-1)])]),_:1}),i[17]||(i[17]=o(" 榮譽推出",-1))])])}const b=r(a,[["render",d]]);export{T as __pageData,b as default};
